stmt.execute("""
    CREATE TABLE products (
        id INT PRIMARY KEY,
        name VARCHAR(100),
        price DECIMAL(10, 2)
    )
    """);

stmt.execute("INSERT INTO products (id, name, price) VALUES (1, 'Klawiatura', 149.99)");
stmt.execute("INSERT INTO products (id, name, price) VALUES (2, 'Mysz', 79.50)");
stmt.execute("INSERT INTO products (id, name, price) VALUES (3, 'Monitor', 899.00)");
System.out.println("Wstawiono 3 wiersze.");
// Jesli podamy wartosci dla WSZYSTKICH kolumn w kolejnosci ich definicji,
// mozna pominac liste kolumn - ale jawne podanie kolumn jest BEZPIECZNIEJSZE
// (nie zepsuje sie, jesli ktos kiedys zmieni kolejnosc kolumn).

try (ResultSet rs = stmt.executeQuery("SELECT * FROM products")) {
    while (rs.next()) {
        System.out.println(" - " + rs.getInt("id") + ": " + rs.getString("name")
                + " (" + rs.getBigDecimal("price") + " zl)");
    }
}
// SELECT to jedyne z DML, ktore NIE zmienia danych - tylko je odczytuje.
// Najprostsza postac: SELECT * FROM tabela (gwiazdka = 'wszystkie kolumny').
// Szczegoly (wybor konkretnych kolumn, aliasy, DISTINCT, LIMIT/OFFSET) -> Lesson10.

System.out.println("=== UPDATE ===");
stmt.execute("UPDATE products SET price = 129.99 WHERE id = 1");
System.out.println("Zaktualizowano cene produktu o id=1.");
// Bez WHERE zmienilyby sie WSZYSTKIE wiersze - zawsze sprawdz warunek!

ResultSet rs = stmt.executeQuery("SELECT * FROM products WHERE id=1");
rs.next();
System.out.println("Nowa cena: " + rs.getBigDecimal("price"));
// Nowa cena: 129.99

System.out.println("=== DELETE ===");
stmt.execute("DELETE FROM products WHERE id = 2");
System.out.println("Usunieto produkt o id=2.");
// UWAGA: DELETE FROM tabela (bez WHERE) usunie WSZYSTKIE wiersze,
// ale zostawi STRUKTURE tabeli - w odroznieniu od DROP TABLE (usuwa strukture),
// i TRUNCATE TABLE (patrz Lesson08_DDL - podobny efekt, inny mechanizm).

ResultSet rs = stmt.executeQuery("SELECT COUNT(*) c FROM products");
rs.next();
System.out.println("Pozostalo wierszy: " + rs.getInt("c"));
// Pozostalo wierszy: 2
